import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { VoluntarioController } from "../controllers/voluntario.controller.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
const controller = new VoluntarioController();
export const voluntarioRoutes = Router();
const permissoesLeitura = ["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"];
const permissoesEscrita = ["ADMINISTRADOR", "OPERADOR"];
const permissaoExclusao = ["ADMINISTRADOR"];
voluntarioRoutes.get("/", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listar.bind(controller)));
voluntarioRoutes.get("/:id", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.buscarPorId.bind(controller)));
voluntarioRoutes.post("/escalas", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarEscala.bind(controller)));
voluntarioRoutes.get("/escalas", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarEscalasGeral.bind(controller)));
voluntarioRoutes.post("/", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criar.bind(controller)));
voluntarioRoutes.put("/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizar.bind(controller)));
voluntarioRoutes.delete("/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.remover.bind(controller)));
voluntarioRoutes.get("/:id/escalas", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarEscalas.bind(controller)));
voluntarioRoutes.put("/escalas/:escalaId", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarEscala.bind(controller)));
voluntarioRoutes.delete("/escalas/:escalaId", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerEscala.bind(controller)));
